import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type StackedThumbnailsProps = Record<string, any>;

const StackedThumbnails: React.FC<StackedThumbnailsProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 8,
  images = [
    "https://malloy.blob.core.windows.net/web/testing/hormozi.jpg",
    "https://malloy.blob.core.windows.net/web/testing/mrbeast.jpg",
    "https://malloy.blob.core.windows.net/web/testing/DOAC.jpg",
    "https://malloy.blob.core.windows.net/web/testing/maxresdefault.jpg"
  ],
  stackOffset = 40,
  rotationIntensity = 3,
  cardBorderRadius = 24,
  shadowOpacity = 0.5,
  staggerFrames = 8,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Constants for layout
  const cardAspectRatio = 16 / 9;
  const cardWidth = width * 0.65; // Cards take up 65% of screen width
  const cardHeight = cardWidth / cardAspectRatio;

  // We want to render the stack such that the first image (index 0) is ON TOP.
  // In HTML/CSS, later elements are on top.
  // So we should reverse the array for rendering if we want index 0 to be visually on top.
  // Wait: if we use z-index or absolute positioning, we can control this.
  // Let's iterate normally but apply z-index descending.

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          perspective: "1000px", // Adds 3D depth
        }}
      >
        {images.map((src, i) => {
          // Animation Logic
          // We want cards to fly in from the bottom.
          // Stagger: Back card (last index) enters first? Or Top card enters first?
          // Let's make the Top card (Index 0) enter LAST to "seal" the stack.
          // Or Back card (Index 3) enters first to build the foundation.
          // Let's do Back-to-Front build.

          // Reverse index for staggering (last item = 0 delay)
          const reverseIndex = images.length - 1 - i;
          
          // Delay per card based on staggerFrames prop
          const delay = reverseIndex * staggerFrames; 
          
          // Spring Physics
          const entranceSpring = spring({
            frame: frame - delay,
            fps,
            config: { damping: 14, stiffness: 80, mass: 1.2 },
          });

          // Interpolations
          // Y Position: Starts at height (offscreen bottom), moves to calculated offset
          const startY = height;
          
          // Stack Offset: Items behind (higher index) move UP slightly (negative Y) so they peek out top
          // Index 0 = Front = 0 offset
          // Index 1 = Behind = -stackOffset
          const finalStackY = -1 * (i * stackOffset);
          
          const translateY = interpolate(
            entranceSpring,
            [0, 1],
            [startY, finalStackY]
          );

          // Scale: Items behind get smaller
          const scale = interpolate(
            entranceSpring,
            [0, 1],
            [0.8, 1 - i * 0.05] // E.g., 1, 0.95, 0.90
          );

          // Opacity: Fade in slightly
          const opacity = interpolate(entranceSpring, [0, 0.5], [0, 1]);

          // Rotation: Alternate slightly to look organic
          // i % 2 === 0 ? rotate positive : negative
          // We multiply by i to increase chaos for further back cards
          const rotationBase = (i % 2 === 0 ? 1 : -1) * (i * 0.5 + 1); 
          const rotateDeg = interpolate(
            entranceSpring,
            [0, 1],
            [0, rotationBase * rotationIntensity]
          );

          // Shadow calculation
          // Only the front card needs a heavy shadow, others get lighter shadows
          const shadowBlur = interpolate(entranceSpring, [0, 1], [0, 60]);
          const currentShadowOpacity = i === 0 ? shadowOpacity : shadowOpacity * 0.5;

          return (
            <AbsoluteFill
              key={i}
              style={{
                justifyContent: "center",
                alignItems: "center",
                zIndex: images.length - i, // Index 0 = Highest Z (Front)
              }}
            >
              <div
                style={{
                  width: cardWidth,
                  height: cardHeight,
                  borderRadius: cardBorderRadius,
                  overflow: "hidden",
                  backgroundColor: "#000", // Fallback for image load
                  transform: `translateY(${translateY}px) scale(${scale}) rotate(${rotateDeg}deg)`,
                  boxShadow: `0px 20px ${shadowBlur}px rgba(0,0,0,${currentShadowOpacity})`,
                  border: "1px solid rgba(255,255,255,0.1)", // Subtle border for dark mode pop
                  opacity,
                  position: "absolute",
                  transition: "none", // Critical for Remotion
                }}
              >
                <Img
                  src={src}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                  }}
                />
                
                {/* Optional: Dark overlay for cards in back to simulate depth */}
                {i > 0 && (
                  <div
                    style={{
                      position: "absolute",
                      top: 0,
                      left: 0,
                      width: "100%",
                      height: "100%",
                      backgroundColor: "black",
                      opacity: i * 0.15, // 0.15 opacity per level of depth
                    }}
                  />
                )}
              </div>
            </AbsoluteFill>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default StackedThumbnails;